// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "./BHouseDetails.sol";
import "./MarketCore.sol";

/// @title BHouseMarket is impletmented for Bhouse.
contract BHouseMarket is MarketCore, AccessControlUpgradeable, PausableUpgradeable, UUPSUpgradeable {
  using BHouseDetails for BHouseDetails.Details;

  bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
  bytes32 public constant WITHDRAWER_ROLE = keccak256("WITHDRAWER_ROLE");
  bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");
  bytes32 public constant DESIGNER_ROLE = keccak256("DESIGNER_ROLE");
  bytes32 public constant BANNER_ROLE = keccak256("BANNER_ROLE");
  bytes32 public constant CANCELER_ROLE = keccak256("CANCELER_ROLE");

  // Upgrade to use multi-coin for payment
  mapping(uint256 => address) tokenPay;
  mapping(address => bool) public tokenWhitelist;

  function initialize(address bcoinCA_, address nftCA_) public initializer {
    __AccessControl_init();
    __Pausable_init();
    __UUPSUpgradeable_init();

    _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
    _setupRole(PAUSER_ROLE, msg.sender);
    _setupRole(WITHDRAWER_ROLE, msg.sender);
    _setupRole(UPGRADER_ROLE, msg.sender);
    _setupRole(DESIGNER_ROLE, msg.sender);
    _setupRole(BANNER_ROLE, msg.sender);
    _setupRole(CANCELER_ROLE, msg.sender);

    bcoinContract = IERC20(bcoinCA_);
    nftContract = IERC721(nftCA_);
    // TODO: require nftCA_ supports 721 interface???

    // default configuration
    taxRate = 500;
    cooldownBeforeCancel = 10;
    cooldownByBlockNumber = 201600;
  }

  function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

  function supportsInterface(bytes4 interfaceId) public view override(AccessControlUpgradeable) returns (bool) {
    return super.supportsInterface(interfaceId);
  }

  function withdraw() external onlyRole(WITHDRAWER_ROLE) {
    bcoinContract.transfer(msg.sender, bcoinContract.balanceOf(address(this)));
  }

  function withdrawV2(address tokenAddress) external onlyRole(WITHDRAWER_ROLE) {
    IERC20(tokenAddress).transfer(msg.sender, IERC20(tokenAddress).balanceOf(address(this)));
  }

  function changeSettings(uint256 taxRate_, uint256 cooldownBeforeCancel_) external onlyRole(DESIGNER_ROLE) {
    require(taxRate_ <= 10000, "taxRate must be in range 0-10000");
    taxRate = taxRate_;
    cooldownBeforeCancel = cooldownBeforeCancel_;
  }

  function setTokenWhitelist(address[] calldata value) external onlyRole(DESIGNER_ROLE) {
    for (uint256 i = 0; i < value.length; i++) {
      tokenWhitelist[value[i]] = true;
    }
  }

  // @dev get bcoin balance on the market
  function getBalance() public view returns (uint256) {
    return bcoinContract.balanceOf(address(this));
  }

  // @dev Creates and begins a new order.
  // @param _tokenId - ID of token, sender must be owner.
  // @param _price - Price of item (in wei).
  // @param _tokenAddress - token contract address
  function createOrder(uint256 _tokenId, uint256 _price, address _tokenAddress) external whenNotPaused {
    // just for safety
    require(_price == uint256(uint128(_price)));

    require(_owns(msg.sender, _tokenId), "Not NFT owner");

    require(!isBlacklist(msg.sender), "blacklist");

    require(tokenWhitelist[_tokenAddress], "Token address not in whitelist");

    // Mapping from token ID to token details.
    uint256 _tokenDetails = nftContract.tokenDetails(_tokenId);

    // validate if this token is sellable
    require(isSellable(_tokenDetails, _price), "not pass sellable rule");

    // check if this user already approveForAll to this marketplace to control the nft
    require(nftContract.isApprovedForAll(msg.sender, address(this)), "not yet approveForAll");

    // save order info
    Order memory order = Order(_tokenId, msg.sender, _price, _tokenDetails, block.timestamp);

    // save token address state
    tokenPay[_tokenId] = _tokenAddress;

    _createOrder(_tokenId, order);
  }

  // @dev Buy on an active order
  // @param _tokenId - ID of nft.
  // @param _price price of the NFT, the price must match the order.price to prevent front-runner attack
  function buy(uint256 _tokenId, uint256 _price) external whenNotPaused {
    // _bid will throw if the bid or funds transfer fails
    _buy(_tokenId, _price);
  }

  // @dev Cancels an order that hasn't been won yet.
  //  Returns the NFT to original owner.
  // @notice This is a state-modifying function that can
  //  be called while the contract is paused.
  // @param _tokenId - ID of token
  function cancelOrder(uint256 _tokenId) external whenNotPaused {
    Order storage order = tokenIdToOrder[_tokenId];
    require(_isOnMarket(order), "order not existed");
    address seller = order.seller;
    require(msg.sender == seller || hasRole(CANCELER_ROLE, msg.sender) || nftContract.ownerOf(_tokenId) == msg.sender);
    require((order.startedAt + cooldownBeforeCancel) < block.timestamp, "cooldown: not cancellable yet");
    _cancelOrder(_tokenId);
  }

  // @dev Cancels an order when the contract is paused.
  //  Only the owner may do this, and NFTs are returned to
  //  the seller. This should only be used in emergencies.
  // @param _tokenId - ID of the NFT.
  function cancelOrderWhenPaused(uint256 _tokenId) external whenPaused onlyRole(CANCELER_ROLE) {
    Order storage order = tokenIdToOrder[_tokenId];
    require(_isOnMarket(order), "order not existed");
    _cancelOrder(_tokenId);
  }

  // @dev remove state type buy in an order
  // @param _tokenId: ID NFT
  function _removeTokenPay(uint256 _tokenId) internal override {
    delete tokenPay[_tokenId];
  }

  // @dev get token pay impl for virtual
  // @param _tokenId: NFT tokenId
  function getTokenPay(uint256 _tokenId) internal view override returns (address) {
    return tokenPay[_tokenId] != address(0) ? tokenPay[_tokenId] : address(bcoinContract);
  }

  // @dev get payment address via list tokenId
  function getTokenPayList(uint256[] calldata _tokenId) public view returns (address[] memory) {
    address[] memory payList = new address[](_tokenId.length);
    for (uint256 i = 0; i < _tokenId.length; i++) {
      payList[i] = tokenPay[_tokenId[i]];
    }
    return payList;
  }

  // @dev Returns order info for an NFT on market.
  // @param _tokenId - ID of NFT on auction.
  function getOrder(
    uint256 _tokenId
  ) external view returns (uint256 tokenDetail, address seller, uint256 price, uint256 startedAt) {
    Order storage order = tokenIdToOrder[_tokenId];
    require(_isOnMarket(order), "order not existed");
    return (order.tokenDetail, order.seller, order.price, order.startedAt);
  }

  function getOrderV2(
    uint256 _tokenId
  )
    external
    view
    returns (uint256 tokenDetail, address seller, uint256 price, uint256 startedAt, address tokenAddress)
  {
    Order storage order = tokenIdToOrder[_tokenId];
    require(_isOnMarket(order), "order not existed");
    return (order.tokenDetail, order.seller, order.price, order.startedAt, tokenPay[_tokenId]);
  }

  function myVersion() public pure returns (uint64 ver_) {
    return 2;
  }

  function pause() public onlyRole(PAUSER_ROLE) {
    _pause();
  }

  function unpause() public onlyRole(PAUSER_ROLE) {
    _unpause();
  }

  function isSellable(uint256 _tokenDetails, uint256 _price) public view returns (bool) {
    uint256 rarity = BHouseDetails.decodeRarity(_tokenDetails);
    RarityRule storage rule = sellableByRarity[rarity];
    uint256 tokenBlockNumber = BHouseDetails.decodeBlockNumber(_tokenDetails);

    return (rule.isSellable &&
      (_price >= rule.minPrice) &&
      (tokenBlockNumber < (block.number - cooldownByBlockNumber)));
  }

  // @dev setSellableRule set which item will be able to put into the market, and at which price
  function setSellableRule(uint256 _rarity, bool _isSellable, uint256 _minPrice) public onlyRole(DESIGNER_ROLE) {
    sellableByRarity[_rarity] = RarityRule(_isSellable, _minPrice);
  }

  function addToBacklist(address[] memory _addresses) public onlyRole(BANNER_ROLE) {
    for (uint256 i = 0; i < _addresses.length; i++) {
      blacklist[_addresses[i]] = true;
    }
  }

  function removeFromBacklist(address[] memory _addresses) public onlyRole(BANNER_ROLE) {
    for (uint256 i = 0; i < _addresses.length; i++) {
      blacklist[_addresses[i]] = false;
    }
  }

  function isBlacklist(address _address) public view returns (bool) {
    return blacklist[_address];
  }

  // @dev setCooldownByBlockNumber changes value of cooldownByBlockNumber
  function setCooldownByBlockNumber(uint256 _new) public onlyRole(DESIGNER_ROLE) {
    cooldownByBlockNumber = _new;
  }

  function dummyDeploy() public view returns (uint256) {
    return 0;
  }
}

contracts/BHouseToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/CountersUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./BHouseDetails.sol";
import "./IBHouseDesign.sol";

contract BHouseToken is ERC721Upgradeable, AccessControlUpgradeable, PausableUpgradeable, UUPSUpgradeable {
  using CountersUpgradeable for CountersUpgradeable.Counter;
  using BHouseDetails for BHouseDetails.Details;

  bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
  bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");
  bytes32 public constant DESIGNER_ROLE = keccak256("DESIGNER_ROLE");
  bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");
  bytes32 public constant TRADER_ROLE = keccak256("TRADER_ROLE");
  bytes32 public constant WITHDRAWER_ROLE = keccak256("WITHDRAWER_ROLE");

  IERC20 public coinToken;
  CountersUpgradeable.Counter public tokenIdCounter;

  // Mapping from owner address to token ID.
  mapping(address => uint256[]) public tokenIds;

  // Mapping from token ID to token details.
  mapping(uint256 => uint256) public tokenDetails;

  // Mapping from token rarity to token count.
  mapping(uint256 => uint256) public tokenByRarity;

  IBHouseDesign public design;
  // Allow network in list can transfer
  mapping(uint256 => bool) public allowTransferInNetwork;

  function initialize(IERC20 coinToken_) public initializer {
    __ERC721_init("Bomb Crypto House", "BHOUSE");
    __AccessControl_init();
    __Pausable_init();
    __UUPSUpgradeable_init();
    coinToken = coinToken_;

    _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
    _setupRole(PAUSER_ROLE, msg.sender);
    _setupRole(UPGRADER_ROLE, msg.sender);
    _setupRole(DESIGNER_ROLE, msg.sender);
    _setupRole(BURNER_ROLE, msg.sender);
    _setupRole(TRADER_ROLE, msg.sender);
    _setupRole(WITHDRAWER_ROLE, msg.sender);
  }

  function pause() public onlyRole(PAUSER_ROLE) {
    _pause();
  }

  function unpause() public onlyRole(PAUSER_ROLE) {
    _unpause();
  }

  function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

  function supportsInterface(bytes4 interfaceId)
    public
    view
    override(ERC721Upgradeable, AccessControlUpgradeable)
    returns (bool)
  {
    return super.supportsInterface(interfaceId);
  }

  function withdraw() external onlyRole(WITHDRAWER_ROLE) {
    coinToken.transfer(msg.sender, coinToken.balanceOf(address(this)));
  }

  /** Burns a list of heroes. */
  function burn(uint256[] memory ids) external onlyRole(BURNER_ROLE) {
    for (uint256 i = 0; i < ids.length; ++i) {
      _burn(ids[i]);
    }
  }

  /** Sets the design. */
  function setDesign(address contractAddress) external onlyRole(DESIGNER_ROLE) {
    design = IBHouseDesign(contractAddress);
  }

  function getMintAvailable() external view returns (uint256[] memory) {
    uint256[] memory mintLimits = design.getMintLimits();
    uint256[] memory result = new uint256[](mintLimits.length);
    for (uint256 i = 0; i < mintLimits.length; ++i) {
      result[i] = mintLimits[i] - tokenByRarity[i];
    }
    return result;
  }

  /** Gets token details for the specified owner. */
  function getTokenDetailsByOwner(address to) external view returns (uint256[] memory) {
    uint256[] storage ids = tokenIds[to];
    uint256[] memory result = new uint256[](ids.length);
    for (uint256 i = 0; i < ids.length; ++i) {
      result[i] = tokenDetails[ids[i]];
    }
    return result;
  }

  /** Mints a token. */
  function mint(uint256 rarity) external {
    // Check global limit.
    uint256[] memory mintLimits = design.getMintLimits();
    require(rarity < mintLimits.length, "Invalid rarity");
    require(tokenByRarity[rarity] < mintLimits[rarity], "Global limit reached");

    // Transfer coin token.
    address to = msg.sender;
    coinToken.transferFrom(to, address(this), design.getMintCost(rarity));

    uint256 id = tokenIdCounter.current();
    tokenDetails[id] = design.createToken(id, rarity);
    tokenIdCounter.increment();

    _safeMint(to, id);
  }

  function _transfer(
    address from,
    address to,
    uint256 tokenId
  ) internal override {
    
    ERC721Upgradeable._transfer(from, to, tokenId);
  }

  function _beforeTokenTransfer(
    address from,
    address to,
    uint256 id,
    uint256
  ) internal override {
    if (from == address(0)) {
      // Mint.
      uint256 details = tokenDetails[id];
      ++tokenByRarity[BHouseDetails.decodeRarity(details)];
    } else {
      // Transfer or burn.
      // Swap and pop.
      uint256[] storage ids = tokenIds[from];
      uint256 index = BHouseDetails.decodeIndex(tokenDetails[id]);
      uint256 lastId = ids[ids.length - 1];
      ids[index] = lastId;
      ids.pop();

      // Update index.
      tokenDetails[lastId] = BHouseDetails.setIndex(tokenDetails[lastId], index);
    }
    if (to == address(0)) {
      // Burn.
      delete tokenDetails[id];
    } else {
      // Transfer or mint.
      uint256[] storage ids = tokenIds[to];
      uint256 index = ids.length;
      ids.push(id);
      tokenDetails[id] = BHouseDetails.setIndex(tokenDetails[id], index);

      // Check user limit.
      require(index + 1 <= design.getTokenLimit(), "User limit reached");
    }
  }

  function removeIdFromOldOwner(uint256 id, address oldOwner) external onlyRole(DESIGNER_ROLE) {

    // check this house id that from oldOwner
    bool checkOldOwner = false;
    uint256[] storage oldOwnerIds = tokenIds[oldOwner];
    for (uint256 i = 0; i < oldOwnerIds.length; ++i) 
        if (id == oldOwnerIds[i]) {
          checkOldOwner = true;
          break;
        }
    require(checkOldOwner, "Old owner wrong");
    // remove from old owner
    uint256 index1 = BHouseDetails.decodeIndex(tokenDetails[id]);
    uint256 lastId = oldOwnerIds[oldOwnerIds.length - 1];
    oldOwnerIds[index1] = lastId;
    oldOwnerIds.pop();
    // Update index.
    tokenDetails[lastId] = BHouseDetails.setIndex(tokenDetails[lastId], index1);
  }

  function fixTransfer(uint256 id, address newOwner, address oldOwner) external {
    require((ownerOf(id) == msg.sender) || hasRole(DESIGNER_ROLE, msg.sender), "Owner of house id or Admin");
    require(newOwner != oldOwner, "Old owner need != owner");
    if (ownerOf(id) == msg.sender) {
      require(newOwner == msg.sender, "New owner needs to be msg sender");
    }

    // check this house id that from oldOwner
    bool checkOldOwner = false;
    uint256[] storage oldOwnerIds = tokenIds[oldOwner];
    for (uint256 i = 0; i < oldOwnerIds.length; ++i) 
        if (id == oldOwnerIds[i]) {
          checkOldOwner = true;
          break;
        }
    require(checkOldOwner, "Old owner wrong");
    // remove from old owner
    uint256 index1 = BHouseDetails.decodeIndex(tokenDetails[id]);
    uint256 lastId = oldOwnerIds[oldOwnerIds.length - 1];
    oldOwnerIds[index1] = lastId;
    oldOwnerIds.pop();
    // Update index.
    tokenDetails[lastId] = BHouseDetails.setIndex(tokenDetails[lastId], index1);

    
    // check this hero id that error
    bool checkOwner = false;
    uint256[] storage ownerIds = tokenIds[newOwner];
    for (uint256 i = 0; i < ownerIds.length; ++i) 
        if (id == ownerIds[i]) {
          checkOwner = true;
          break;
        }
    require(!checkOwner, "Already owner");
    // add to current owner
    uint256 index = ownerIds.length;
    ownerIds.push(id);
    tokenDetails[id] = BHouseDetails.setIndex(tokenDetails[id], index);
  }

  function fixMint(uint256 id, address newOwner) external onlyRole(DESIGNER_ROLE) {
    // check this house id that error
    bool checkOwner = false;
    uint256[] storage ownerIds = tokenIds[newOwner];
    for (uint256 i = 0; i < ownerIds.length; ++i) 
        if (id == ownerIds[i]) {
          checkOwner = true;
          break;
        }
    require(!checkOwner, "Already owner");
    // add to current owner
    uint256 index = ownerIds.length;
    ownerIds.push(id);
    tokenDetails[id] = BHouseDetails.setIndex(tokenDetails[id], index);
  }

  /** Burns a list of houses. */
  function burnWallet(address wallet) external onlyRole(BURNER_ROLE) {
    require(tokenIds[wallet].length > 0, "Need own a house");
    uint256[] memory ids = tokenIds[wallet];
    for (uint256 i = 0; i < ids.length; ++i) {
      _burn(ids[i]);
    }
  }

  function dummyDeploy5() public view returns (uint256) {
    return 0;
  }

  function dummyDeploy(uint256 dummy) public view returns (uint256) {
    return 0;
  }
}

contracts/ChampionSBT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/utils/CountersUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

contract ChampionSBT  is ERC721Upgradeable, AccessControlUpgradeable, UUPSUpgradeable {
    
    using CountersUpgradeable for CountersUpgradeable.Counter;

    CountersUpgradeable.Counter private _tokenIds;

    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");
    bytes32 public constant DESIGNER_ROLE = keccak256("DESIGNER_ROLE");
    
    mapping(uint256 => string) public tokenNames;

    function initialize() public initializer {
        __ERC721_init("Bomb Crypto Champion", "BCC");
        __AccessControl_init();
        __UUPSUpgradeable_init();
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(UPGRADER_ROLE, msg.sender);
        _grantRole(DESIGNER_ROLE, msg.sender);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

    function supportsInterface(bytes4 interfaceId) public view override(ERC721Upgradeable, AccessControlUpgradeable)
    returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    function mintSBT(address recipient, string memory _SBTname) external onlyRole(DESIGNER_ROLE) returns (uint256) {
        _tokenIds.increment();

        uint256 newTokenId = _tokenIds.current();
        _mint(recipient, newTokenId);

        tokenNames[newTokenId] = _SBTname;

        return newTokenId;
    }

    function _beforeTokenTransfer(address from, address to, uint256 tokenId, uint256 batchSize)
        internal
        override 
    {
        require(from == address(0), "Token is not transferable");
        super._beforeTokenTransfer(from, to, tokenId, batchSize);
    }
}

contracts/ERC404.sol.content:
//SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

abstract contract Ownable {
    event OwnershipTransferred(address indexed user, address indexed newOwner);

    error Unauthorized();
    error InvalidOwner();

    address public owner;

    modifier onlyOwner() virtual {
        if (msg.sender != owner) revert Unauthorized();

        _;
    }

    constructor(address _owner) {
        if (_owner == address(0)) revert InvalidOwner();

        owner = _owner;

        emit OwnershipTransferred(address(0), _owner);
    }

    function transferOwnership(address _owner) public virtual onlyOwner {
        if (_owner == address(0)) revert InvalidOwner();

        owner = _owner;

        emit OwnershipTransferred(msg.sender, _owner);
    }

    function revokeOwnership() public virtual onlyOwner {
        owner = address(0);

        emit OwnershipTransferred(msg.sender, address(0));
    }
}

abstract contract ERC721Receiver {
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external virtual returns (bytes4) {
        return ERC721Receiver.onERC721Received.selector;
    }
}

/// @notice ERC404
///         A gas-efficient, mixed ERC20 / ERC721 implementation
///         with native liquidity and fractionalization.
///
///         This is an experimental standard designed to integrate
///         with pre-existing ERC20 / ERC721 support as smoothly as
///         possible.
///
/// @dev    In order to support full functionality of ERC20 and ERC721
///         supply assumptions are made that slightly constraint usage.
///         Ensure decimals are sufficiently large (standard 18 recommended)
///         as ids are effectively encoded in the lowest range of amounts.
///
///         NFTs are spent on ERC20 functions in a FILO queue, this is by
///         design.
///
abstract contract ERC404 is Ownable {
    // Events
    event ERC20Transfer(
        address indexed from,
        address indexed to,
        uint256 amount
    );
    event Approval(
        address indexed owner,
        address indexed spender,
        uint256 amount
    );
    event Transfer(
        address indexed from,
        address indexed to,
        uint256 indexed id
    );
    event ERC721Approval(
        address indexed owner,
        address indexed spender,
        uint256 indexed id
    );
    event ApprovalForAll(
        address indexed owner,
        address indexed operator,
        bool approved
    );

    // Errors
    error NotFound();
    error AlreadyExists();
    error InvalidRecipient();
    error InvalidSender();
    error UnsafeRecipient();

    // Metadata
    /// @dev Token name
    string public name;

    /// @dev Token symbol
    string public symbol;

    /// @dev Decimals for fractional representation
    uint8 public immutable decimals;

    /// @dev Total supply in fractionalized representation
    uint256 public immutable totalSupply;

    /// @dev Current mint counter, monotonically increasing to ensure accurate ownership
    uint256 public minted;

    // Mappings
    /// @dev Balance of user in fractional representation
    mapping(address => uint256) public balanceOf;

    /// @dev Allowance of user in fractional representation
    mapping(address => mapping(address => uint256)) public allowance;

    /// @dev Approval in native representaion
    mapping(uint256 => address) public getApproved;

    /// @dev Approval for all in native representation
    mapping(address => mapping(address => bool)) public isApprovedForAll;

    /// @dev Owner of id in native representation
    mapping(uint256 => address) internal _ownerOf;

    /// @dev Array of owned ids in native representation
    mapping(address => uint256[]) internal _owned;

    /// @dev Tracks indices for the _owned mapping
    mapping(uint256 => uint256) internal _ownedIndex;

    /// @dev Addresses whitelisted from minting / burning for gas savings (pairs, routers, etc)
    mapping(address => bool) public whitelist;

    // Constructor
    constructor(
        string memory _name,
        string memory _symbol,
        uint8 _decimals,
        uint256 _totalNativeSupply,
        address _owner
    ) Ownable(_owner) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
        totalSupply = _totalNativeSupply * (10 ** decimals);
    }

    /// @notice Initialization function to set pairs / etc
    ///         saving gas by avoiding mint / burn on unnecessary targets
    function setWhitelist(address target, bool state) public onlyOwner {
        whitelist[target] = state;
    }

    /// @notice Function to find owner of a given native token
    function ownerOf(uint256 id) public view virtual returns (address owner) {
        owner = _ownerOf[id];

        if (owner == address(0)) {
            revert NotFound();
        }
    }

    /// @notice tokenURI must be implemented by child contract
    function tokenURI(uint256 id) public view virtual returns (string memory);

    /// @notice Function for token approvals
    /// @dev This function assumes id / native if amount less than or equal to current max id
    function approve(
        address spender,
        uint256 amountOrId
    ) public virtual returns (bool) {
        if (amountOrId <= minted && amountOrId > 0) {
            address owner = _ownerOf[amountOrId];

            if (msg.sender != owner && !isApprovedForAll[owner][msg.sender]) {
                revert Unauthorized();
            }

            getApproved[amountOrId] = spender;

            emit Approval(owner, spender, amountOrId);
        } else {
            allowance[msg.sender][spender] = amountOrId;

            emit Approval(msg.sender, spender, amountOrId);
        }

        return true;
    }

    /// @notice Function native approvals
    function setApprovalForAll(address operator, bool approved) public virtual {
        isApprovedForAll[msg.sender][operator] = approved;

        emit ApprovalForAll(msg.sender, operator, approved);
    }

    /// @notice Function for mixed transfers
    /// @dev This function assumes id / native if amount less than or equal to current max id
    function transferFrom(
        address from,
        address to,
        uint256 amountOrId
    ) public virtual {
        if (amountOrId <= minted) {
            if (from != _ownerOf[amountOrId]) {
                revert InvalidSender();
            }

            if (to == address(0)) {
                revert InvalidRecipient();
            }

            if (
                msg.sender != from &&
                !isApprovedForAll[from][msg.sender] &&
                msg.sender != getApproved[amountOrId]
            ) {
                revert Unauthorized();
            }

            balanceOf[from] -= _getUnit();

            unchecked {
                balanceOf[to] += _getUnit();
            }

            _ownerOf[amountOrId] = to;
            delete getApproved[amountOrId];

            // update _owned for sender
            uint256 updatedId = _owned[from][_owned[from].length - 1];
            _owned[from][_ownedIndex[amountOrId]] = updatedId;
            // pop
            _owned[from].pop();
            // update index for the moved id
            _ownedIndex[updatedId] = _ownedIndex[amountOrId];
            // push token to to owned
            _owned[to].push(amountOrId);
            // update index for to owned
            _ownedIndex[amountOrId] = _owned[to].length - 1;

            emit Transfer(from, to, amountOrId);
            emit ERC20Transfer(from, to, _getUnit());
        } else {
            uint256 allowed = allowance[from][msg.sender];

            if (allowed != type(uint256).max)
                allowance[from][msg.sender] = allowed - amountOrId;

            _transfer(from, to, amountOrId);
        }
    }

    /// @notice Function for fractional transfers
    function transfer(
        address to,
        uint256 amount
    ) public virtual returns (bool) {
        return _transfer(msg.sender, to, amount);
    }

    /// @notice Function for native transfers with contract support
    function safeTransferFrom(
        address from,
        address to,
        uint256 id
    ) public virtual {
        transferFrom(from, to, id);

        if (
            to.code.length != 0 &&
            ERC721Receiver(to).onERC721Received(msg.sender, from, id, "") !=
            ERC721Receiver.onERC721Received.selector
        ) {
            revert UnsafeRecipient();
        }
    }

    /// @notice Function for native transfers with contract support and callback data
    function safeTransferFrom(
        address from,
        address to,
        uint256 id,
        bytes calldata data
    ) public virtual {
        transferFrom(from, to, id);

        if (
            to.code.length != 0 &&
            ERC721Receiver(to).onERC721Received(msg.sender, from, id, data) !=
            ERC721Receiver.onERC721Received.selector
        ) {
            revert UnsafeRecipient();
        }
    }

    /// @notice Internal function for fractional transfers
    function _transfer(
        address from,
        address to,
        uint256 amount
    ) internal returns (bool) {
        uint256 unit = _getUnit();
        uint256 balanceBeforeSender = balanceOf[from];
        uint256 balanceBeforeReceiver = balanceOf[to];

        balanceOf[from] -= amount;

        unchecked {
            balanceOf[to] += amount;
        }

        // Skip burn for certain addresses to save gas
        if (!whitelist[from]) {
            uint256 tokens_to_burn = (balanceBeforeSender / unit) -
                (balanceOf[from] / unit);
            for (uint256 i = 0; i < tokens_to_burn; i++) {
                _burn(from);
            }
        }

        // Skip minting for certain addresses to save gas
        if (!whitelist[to]) {
            uint256 tokens_to_mint = (balanceOf[to] / unit) -
                (balanceBeforeReceiver / unit);
            for (uint256 i = 0; i < tokens_to_mint; i++) {
                _mint(to);
            }
        }

        emit ERC20Transfer(from, to, amount);
        return true;
    }

    // Internal utility logic
    function _getUnit() internal view returns (uint256) {
        return 10 ** decimals;
    }

    function _mint(address to) internal virtual {
        if (to == address(0)) {
            revert InvalidRecipient();
        }

        unchecked {
            minted++;
        }

        uint256 id = minted;

        if (_ownerOf[id] != address(0)) {
            revert AlreadyExists();
        }

        _ownerOf[id] = to;
        _owned[to].push(id);
        _ownedIndex[id] = _owned[to].length - 1;

        emit Transfer(address(0), to, id);
    }

    function _burn(address from) internal virtual {
        if (from == address(0)) {
            revert InvalidSender();
        }

        uint256 id = _owned[from][_owned[from].length - 1];
        _owned[from].pop();
        delete _ownedIndex[id];
        delete _ownerOf[id];
        delete getApproved[id];

        emit Transfer(from, address(0), id);
    }

    function _setNameSymbol(
        string memory _name,
        string memory _symbol
    ) internal {
        name = _name;
        symbol = _symbol;
    }
}

